interface.preamble:
        struct Camera {
            viewProj: mat4x4<f32>,
            view: mat4x4<f32>,
            proj: mat4x4<f32>,
            invViewProj: mat4x4<f32>,
            invView: mat4x4<f32>,
            invProj: mat4x4<f32>,

            eyePos: vec3<f32>,
            simTime: f32,

            zNear: f32,
            zFar: f32,
            fovRads: f32,
            aspect: f32,
            _padEnd: vec4<f32>
        };

@group(0) @binding(0) var<storage, read_write> b_blocks: array<f32>;
@group(1) @binding(0) var<uniform> camera: Camera;
const B_blocks_STRIDE: u32 = 14u;
const EA_INVOCATIONS: u32 = 64u;

interface.epilogue:
@compute @workgroup_size(64)
fn cs_main(@builtin(global_invocation_id) id: vec3<u32>) {
    _ = arrayLength(&b_blocks);
    _ = camera.simTime;
    if (id.x >= EA_INVOCATIONS) { return; }
    placeBlocks(id.x);
}
